//! ST7735 160x80 text firmware: one line of 8x16 dot-matrix text.
//!
//! This is the device half of P1. The PC preview (`preview_st7735.py`) and this
//! firmware draw from the *same* glyph table (`src/font8x16.rs`, generated by
//! `tools/font8x16_gen.py`), so "what the preview shows" and "what the glass
//! shows" are the same bytes, not two independent drawings.
//!
//! It composes the whole 160x80 frame in RAM, prints a CRC32 of that frame over
//! the serial port, and only then pushes it to the panel. That CRC is the
//! parity proof: compute the same CRC over the preview's `--raw` dump and they
//! must match.
//!
//! Wiring (same as the working st7735-esp32 project on this desk):
//!   SCLK=GPIO18  MOSI=GPIO23  CS=GPIO5  DC=GPIO4  RST=GPIO15  BL=GPIO2
//!
//! Panel quirks measured on this exact module: landscape 160x80 needs
//! MADCTL=0x60 (MV|MX), offsets (0,24), and NO inversion.

#![no_std]
#![no_main]

use esp_hal::delay::Delay;
use esp_hal::gpio::{Level, Output, OutputConfig};
use esp_hal::main;
use esp_hal::spi::master::{Config as SpiConfig, Spi};
use esp_hal::spi::Mode as SpiMode;
use esp_hal::time::Rate;
use esp_hal::Blocking;
use esp_println::println;

mod font8x16;

esp_bootloader_esp_idf::esp_app_desc!();

// ============================ what to show ============================

/// The one line to draw. 20 characters fit across 160px at 8px each; anything
/// longer is cut and marked with '>' exactly like the preview does.
const TEXT: &str = "CPU 33.5% 34C";

/// Centre the line horizontally. `false` = left margin of MARGIN_X pixels.
const CENTER_ME: bool = true;
const MARGIN_X: usize = 2;

/// Vertically centred in the panel: rows 32..48 hold a 16px cell in 80px.
const CELL_Y: usize = (LCD_H - font8x16::CELL_H) / 2;

const FG: u16 = 0xFFFF;
const BG: u16 = 0x0000;

// ============================ panel wiring ============================

const LCD_W: usize = 160;
const LCD_H: usize = 80;
const FRAME_BYTES: usize = LCD_W * LCD_H * 2;

const MADCTL: u8 = 0x60; // MV (rotate 90) | MX (mirror) -> landscape, origin top-left
const OFF_X: u16 = 0;
const OFF_Y: u16 = 24;
const INVERT: bool = false;
const SPI_MHZ: u32 = 20;

// ============================ ST7735 commands ============================

const CMD_SWRESET: u8 = 0x01;
const CMD_SLPOUT: u8 = 0x11;
const CMD_NORON: u8 = 0x13;
const CMD_INVOFF: u8 = 0x20;
const CMD_INVON: u8 = 0x21;
const CMD_DISPON: u8 = 0x29;
const CMD_CASET: u8 = 0x2A;
const CMD_RASET: u8 = 0x2B;
const CMD_RAMWR: u8 = 0x2C;
const CMD_MADCTL: u8 = 0x36;
const CMD_COLMOD: u8 = 0x3A;
const CMD_FRMCTR1: u8 = 0xB1;
const CMD_FRMCTR2: u8 = 0xB2;
const CMD_FRMCTR3: u8 = 0xB3;
const CMD_INVCTR: u8 = 0xB4;
const CMD_PWCTR1: u8 = 0xC0;
const CMD_PWCTR2: u8 = 0xC1;
const CMD_PWCTR3: u8 = 0xC2;
const CMD_PWCTR4: u8 = 0xC3;
const CMD_PWCTR5: u8 = 0xC4;
const CMD_VMCTR1: u8 = 0xC5;
const CMD_GMCTRP1: u8 = 0xE0;
const CMD_GMCTRN1: u8 = 0xE1;

/// The whole frame lives in RAM: 25600 bytes, the exact size of the preview's
/// `--raw` dump, so the CRC covers pixel-for-pixel the same image.
static mut FRAME: [u8; FRAME_BYTES] = [0; FRAME_BYTES];

struct St7735<'d> {
    spi: Spi<'d, Blocking>,
    cs: Output<'d>,
    dc: Output<'d>,
}

impl<'d> St7735<'d> {
    fn cmd(&mut self, cmd: u8, data: &[u8]) {
        self.cs.set_low();
        self.dc.set_low();
        let _ = self.spi.write(&[cmd]);
        if !data.is_empty() {
            self.dc.set_high();
            let _ = self.spi.write(data);
        }
        self.cs.set_high();
    }

    fn pixels(&mut self, data: &[u8]) {
        self.cs.set_low();
        self.dc.set_high();
        let _ = self.spi.write(data);
        self.cs.set_high();
    }

    fn set_window(&mut self, x0: u16, y0: u16, x1: u16, y1: u16) {
        let (ax, bx) = (x0 + OFF_X, x1 + OFF_X);
        let (ay, by) = (y0 + OFF_Y, y1 + OFF_Y);
        let mut b = [0u8; 4];
        b[0..2].copy_from_slice(&ax.to_be_bytes());
        b[2..4].copy_from_slice(&bx.to_be_bytes());
        self.cmd(CMD_CASET, &b);
        b[0..2].copy_from_slice(&ay.to_be_bytes());
        b[2..4].copy_from_slice(&by.to_be_bytes());
        self.cmd(CMD_RASET, &b);
        self.cmd(CMD_RAMWR, &[]);
    }

    fn init(&mut self, delay: &mut Delay) {
        self.cmd(CMD_SWRESET, &[]);
        delay.delay_millis(150);
        self.cmd(CMD_SLPOUT, &[]);
        delay.delay_millis(120);

        self.cmd(CMD_FRMCTR1, &[0x01, 0x2C, 0x2D]);
        self.cmd(CMD_FRMCTR2, &[0x01, 0x2C, 0x2D]);
        self.cmd(CMD_FRMCTR3, &[0x01, 0x2C, 0x2D, 0x01, 0x2C, 0x2D]);
        self.cmd(CMD_INVCTR, &[0x07]);
        self.cmd(CMD_PWCTR1, &[0xA2, 0x02, 0x84]);
        self.cmd(CMD_PWCTR2, &[0xC5]);
        self.cmd(CMD_PWCTR3, &[0x0A, 0x00]);
        self.cmd(CMD_PWCTR4, &[0x8A, 0x2A]);
        self.cmd(CMD_PWCTR5, &[0x8A, 0xEE]);
        self.cmd(CMD_VMCTR1, &[0x0E]);
        self.cmd(if INVERT { CMD_INVON } else { CMD_INVOFF }, &[]);
        self.cmd(CMD_MADCTL, &[MADCTL]);
        self.cmd(CMD_COLMOD, &[0x05]); // 16 bits per pixel
        self.cmd(
            CMD_GMCTRP1,
            &[
                0x02, 0x1C, 0x07, 0x12, 0x37, 0x32, 0x29, 0x2D, 0x29, 0x25, 0x2B, 0x39, 0x00, 0x01,
                0x03, 0x10,
            ],
        );
        self.cmd(
            CMD_GMCTRN1,
            &[
                0x03, 0x1D, 0x07, 0x06, 0x2E, 0x2C, 0x29, 0x2D, 0x2E, 0x2E, 0x37, 0x3F, 0x00, 0x00,
                0x02, 0x10,
            ],
        );
        self.cmd(CMD_NORON, &[]);
        delay.delay_millis(10);
        self.cmd(CMD_DISPON, &[]);
        delay.delay_millis(100);
    }

    /// Push the whole RAM frame in one window, in chunks the SPI can swallow.
    fn blit(&mut self, frame: &[u8]) {
        self.set_window(0, 0, LCD_W as u16 - 1, LCD_H as u16 - 1);
        for chunk in frame.chunks(480) {
            self.pixels(chunk);
        }
    }
}

// ============================ text into the frame ============================

/// Fit a line into `LCD_W / CELL_W` cells: non-ASCII becomes '?', overflow gets
/// a '>' marker. Mirrors `prepare_text()` in preview_st7735.py exactly.
fn fit_text(text: &str, cols: usize) -> ([u8; 32], usize) {
    let mut buf = [b' '; 32];
    let mut n = 0;
    for ch in text.bytes() {
        if n >= cols || n >= buf.len() {
            break;
        }
        buf[n] = if (32..=126).contains(&ch) { ch } else { b'?' };
        n += 1;
    }
    if n == cols {
        // over-long input: cut one more cell and mark it
        let mut over = false;
        for ch in text.bytes().skip(cols) {
            let _ = ch;
            over = true;
            break;
        }
        if over {
            buf[cols - 1] = b'>';
        }
    }
    (buf, n)
}

fn put_pixel(frame: &mut [u8], x: usize, y: usize, colour: u16) {
    if x >= LCD_W || y >= LCD_H {
        return;
    }
    let at = (y * LCD_W + x) * 2;
    frame[at] = (colour >> 8) as u8;
    frame[at + 1] = (colour & 0xFF) as u8;
}

/// Draw one line of 8x16 cells; MSB of each row byte is the leftmost pixel.
fn draw_line(frame: &mut [u8], text: &[u8], cells: usize, x0: usize, y0: usize) {
    for (cell, &ch) in text[..cells].iter().enumerate() {
        let idx = if (font8x16::FIRST..=font8x16::LAST).contains(&ch) {
            (ch - font8x16::FIRST) as usize
        } else {
            (b' ' - font8x16::FIRST) as usize
        };
        for row in 0..font8x16::CELL_H {
            let bits = font8x16::GLYPHS[idx][row];
            for col in 0..font8x16::CELL_W {
                let on = (bits >> (7 - col)) & 1 == 1;
                put_pixel(frame,
                          x0 + cell * font8x16::CELL_W + col,
                          y0 + row,
                          if on { FG } else { BG });
            }
        }
    }
}

/// CRC32/IEEE, bitwise, same polynomial and init as zlib.crc32 on the PC side.
fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFF_FFFFu32;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            let mask = (crc & 1).wrapping_neg();
            crc = (crc >> 1) ^ (0xEDB8_8320 & mask);
        }
    }
    !crc
}

#[panic_handler]
fn panic(info: &core::panic::PanicInfo) -> ! {
    println!("PANIC {}", info);
    loop {}
}

#[main]
fn main() -> ! {
    let peripherals = esp_hal::init(esp_hal::Config::default());
    let mut delay = Delay::new();

    println!();
    println!("=== st7735-text 160x80 / 8x16 dot matrix ===");

    let mut bl = Output::new(peripherals.GPIO2, Level::High, OutputConfig::default());
    bl.set_high();

    let mut rst = Output::new(peripherals.GPIO15, Level::High, OutputConfig::default());
    rst.set_low();
    delay.delay_millis(20);
    rst.set_high();
    delay.delay_millis(120);

    let spi = Spi::new(
        peripherals.SPI2,
        SpiConfig::default()
            .with_frequency(Rate::from_mhz(SPI_MHZ))
            .with_mode(SpiMode::_0),
    )
    .unwrap()
    .with_sck(peripherals.GPIO18)
    .with_mosi(peripherals.GPIO23);

    let cs = Output::new(peripherals.GPIO5, Level::High, OutputConfig::default());
    let dc = Output::new(peripherals.GPIO4, Level::Low, OutputConfig::default());

    let mut lcd = St7735 { spi, cs, dc };
    lcd.init(&mut delay);
    println!("init done: MADCTL=0x{:02X} OFF=({},{}) INVERT={} SPI={}MHz",
             MADCTL, OFF_X, OFF_Y, INVERT, SPI_MHZ);

    // ---- compose the frame exactly like the preview does ----
    let frame = unsafe { &mut *core::ptr::addr_of_mut!(FRAME) };
    for byte in frame.iter_mut() {
        *byte = 0; // black background, both colour bytes are 0x0000
    }

    let cols = LCD_W / font8x16::CELL_W;
    let (text, cells) = fit_text(TEXT, cols);
    let width = cells * font8x16::CELL_W;
    let x0 = if CENTER_ME && width < LCD_W { (LCD_W - width) / 2 } else { MARGIN_X };
    draw_line(frame, &text, cells, x0, CELL_Y);

    let sum = crc32(frame);
    let shown = core::str::from_utf8(&text[..cells]).unwrap_or("?");
    println!("text={:?} cells={} x={} y={} w={}px", shown, cells, x0, CELL_Y, width);
    println!("FRAME {}x{} crc=0x{:08X} bytes={}", LCD_W, LCD_H, sum, FRAME_BYTES);

    // ---- push it ----
    lcd.blit(frame);
    println!("blit done");
    println!("READY");

    loop {
        delay.delay_millis(1000);
    }
}
